def echo(depth, width):
    if depth == 0:
        return 0
    subtotal = 0
    for index in range(width):
        if index == 1:
            subtotal += echo(depth - 1, 1)
        else:
            subtotal += index + depth
    print(depth, subtotal)
    return subtotal
answer = echo(2, 3)
print("sum", answer)
